export const SCREENSHOT_CORNER_DEFAULT_TIMEOUT_MILLIS=6e3,SCREENSHOT_SOUND_POINTS=["startAnimation","saveScreenshotAndToast"],SCROLL_CAPTURE_STEPS=["enqueueScrollCaptureRequest","requestScrollCapture","onScrollButtonClicked","executeBatchScrollCapture","createLongScreenshotIntent"],SCREENSHOT_EVENT={SCREENSHOT_INTERACTION_TIMEOUT:"SCREENSHOT_INTERACTION_TIMEOUT",SCREENSHOT_REENTERED:"SCREENSHOT_REENTERED"},SHELF_SWIPE={DELETE:"delete",SHARE:"share"};export function isScreenshotSoundAt(t){return SCREENSHOT_SOUND_POINTS.includes(t)}export function createScreenshotShelf(t={}){const r=Number.isFinite(t.timeoutMs)&&t.timeoutMs>0?t.timeoutMs:6e3,n=typeof t.now=="function"?t.now:()=>performance.now();let e="idle",E=0;return{enter(){e="shown",E=n()},touch(){return e!=="shown"?null:(E=n(),SCREENSHOT_EVENT.SCREENSHOT_REENTERED)},swipe(o){return e!=="shown"||o!==SHELF_SWIPE.DELETE&&o!==SHELF_SWIPE.SHARE?null:(e="idle",o)},tick(){return e!=="shown"?null:n()-E>=r?(e="idle",SCREENSHOT_EVENT.SCREENSHOT_INTERACTION_TIMEOUT):null},state:()=>e,remainingMs:()=>e==="shown"?Math.max(0,r-(n()-E)):0,timeoutMs:()=>r}}
